import React, { useCallback, useEffect, useMemo, useRef, useState, type ReactNode } from 'react';
import { AccessibilityInfo, Platform, Pressable, StyleSheet, View, type GestureResponderEvent } from 'react-native';
import { Canvas, Fill, Shader, Skia } from '@shopify/react-native-skia';
import { Easing, useDerivedValue, useSharedValue, withTiming } from 'react-native-reanimated';
import { originFrom, rippleUniforms, type RippleConfig } from './rippleMath';

export type RippleSize = { width: number; height: number };
export type RippleFeedback = 'start' | 'settle';
export type RippleRevealProps = {
  width: number;
  height: number;
  /** Each theme is a Skia shader node, for example <LinearGradient /> or <ImageShader />. Sized by the box. */
  themeA: (size: RippleSize) => ReactNode;
  themeB: (size: RippleSize) => ReactNode;
  /** RN content drawn above the canvas, such as a title. It never receives touches. */
  overlay?: (showing: 'a' | 'b') => ReactNode;
  initial?: 'a' | 'b';
  label?: string;
  durationMs?: number;
  /** Wave height in pixels at the start of the reveal. */
  amplitude?: number;
  wavelength?: number;
  ringWidth?: number;
  onChange?: (showing: 'a' | 'b') => void;
  onFeedback?: (event: RippleFeedback) => void;
  reducedMotion?: boolean;
};

// The same maths as rippleMath.ts: a front that grows from the tap, with a decaying wave around it.
// Two child shaders arrive as `a` and `b`. `oldIsB` says which one the front is replacing.
const SOURCE = `
uniform shader a;
uniform shader b;
uniform float2 size;
uniform float2 origin;
uniform float radius;
uniform float ring;
uniform float wavelength;
uniform float amp;
uniform float oldIsB;
uniform float fade;
half4 main(float2 p) {
  float2 delta = p - origin;
  float d = length(delta);
  float edge = d - radius;
  float off = sin(edge / max(wavelength, 1.0) * 6.2831853) * exp(-abs(edge) / max(ring, 1.0)) * amp;
  float2 q = p + (d > 0.0001 ? delta / d * off : float2(0.0));
  half4 ca = a.eval(q);
  half4 cb = b.eval(q);
  half4 oldC = oldIsB > 0.5 ? cb : ca;
  half4 newC = oldIsB > 0.5 ? ca : cb;
  float cover = fade >= 0.0 ? 1.0 - fade : smoothstep(-1.5, 1.5, edge);
  half4 c = mix(newC, oldC, half(cover));
  float crest = amp > 0.0 ? abs(off) / amp : 0.0;
  float lit = fade >= 0.0 ? 0.0 : crest * (1.0 - smoothstep(0.0, ring, abs(edge))) * 0.16;
  c.rgb = min(c.rgb + half3(lit), half3(1.0));
  return c;
}`;
const effect = Skia.RuntimeEffect.Make(SOURCE);

export function RippleReveal({ width, height, themeA, themeB, overlay, initial = 'a', label = 'Switch theme', durationMs = 1100, amplitude = 14, wavelength = 38, ringWidth = 64, onChange, onFeedback, reducedMotion }: RippleRevealProps) {
  const [showing, setShowing] = useState<'a' | 'b'>(initial);
  // The overlay switches once the front is about halfway, so text stays readable over both themes.
  const [overlayShowing, setOverlayShowing] = useState<'a' | 'b'>(initial);
  const overlayTimer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = reducedMotion ?? systemReduce;
  const progress = useSharedValue(1);
  const originX = useSharedValue(width / 2);
  const originY = useSharedValue(height / 2);
  const oldIsB = useSharedValue(initial === 'a' ? 1 : 0);
  const busy = useRef(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const latest = useRef({ onChange, onFeedback });
  latest.current = { onChange, onFeedback };
  useEffect(() => {
    let alive = true;
    AccessibilityInfo.isReduceMotionEnabled().then(v => { if (alive) setSystemReduce(v); }).catch(() => {});
    const sub = AccessibilityInfo.addEventListener('reduceMotionChanged', setSystemReduce);
    return () => { alive = false; sub.remove(); if (timer.current) clearTimeout(timer.current); if (overlayTimer.current) clearTimeout(overlayTimer.current); };
  }, []);
  const cfg = useMemo<RippleConfig>(() => ({ width, height, ringWidth, wavelength, amplitude }), [width, height, ringWidth, wavelength, amplitude]);
  const uniforms = useDerivedValue(() => rippleUniforms(progress.value, { x: originX.value, y: originY.value }, oldIsB.value > 0.5, reduce, cfg));
  const reveal = useCallback((x: number, y: number) => {
    if (busy.current) return;
    busy.current = true;
    const next = showing === 'a' ? 'b' : 'a';
    const o = originFrom(x, y, width, height);
    originX.value = o.x;
    originY.value = o.y;
    oldIsB.value = showing === 'b' ? 1 : 0;
    const ms = reduce ? 180 : durationMs;
    progress.value = 0;
    progress.value = withTiming(1, { duration: ms, easing: Easing.linear });
    setShowing(next);
    overlayTimer.current = setTimeout(() => setOverlayShowing(next), ms * 0.4);
    latest.current.onChange?.(next);
    latest.current.onFeedback?.('start');
    AccessibilityInfo.announceForAccessibility?.(`${label}: showing theme ${next === 'a' ? 'one' : 'two'}`);
    timer.current = setTimeout(() => { busy.current = false; latest.current.onFeedback?.('settle'); }, ms);
  }, [showing, width, height, reduce, durationMs, label, originX, originY, oldIsB, progress]);
  const onPress = useCallback((event: GestureResponderEvent) => reveal(event.nativeEvent.locationX, event.nativeEvent.locationY), [reveal]);
  const size = { width, height };
  return (
    <View style={{ width, height, borderRadius: 22, overflow: 'hidden', alignSelf: 'center' }}>
      <Canvas pointerEvents="none" style={styles.fill}>
        <Fill>
          {effect ? <Shader source={effect} uniforms={uniforms}>{themeA(size)}{themeB(size)}</Shader> : null}
        </Fill>
      </Canvas>
      <View pointerEvents="none" style={styles.fill}>{overlay?.(overlayShowing)}</View>
      <Pressable accessibilityRole="button" accessibilityLabel={label} accessibilityHint="Reveals the other theme from where you tap" accessibilityState={{ selected: showing === 'b' }} onPress={onPress} style={styles.fill} {...(Platform.OS === 'web' ? { focusable: true } : {})} />
    </View>
  );
}
const styles = StyleSheet.create({ fill: { position: 'absolute', left: 0, top: 0, right: 0, bottom: 0 } });

// Pure geometry for the Theme Reveal. Every function is a worklet so Skia and
// Reanimated can call it on the UI thread; plain JS (tests, web preview) ignores the tag.
export type RippleConfig = { width: number; height: number; ringWidth: number; wavelength: number; amplitude: number };
export type RipplePoint = { x: number; y: number };

export function clamp(value: number, min: number, max: number) {
  'worklet';
  return Math.max(min, Math.min(max, Number.isFinite(value) ? value : min));
}
// A tap outside the box (or a keyboard "press" with no coordinates) starts from the centre.
export function originFrom(x: number, y: number, width: number, height: number): RipplePoint {
  'worklet';
  const ok = Number.isFinite(x) && Number.isFinite(y) && x >= 0 && y >= 0 && x <= width && y <= height && !(x === 0 && y === 0);
  return ok ? { x, y } : { x: width / 2, y: height / 2 };
}
// Distance from the origin to the farthest corner: the reveal must pass it to finish.
export function farthestCorner(ox: number, oy: number, width: number, height: number) {
  'worklet';
  const dx = Math.max(ox, width - ox), dy = Math.max(oy, height - oy);
  return Math.sqrt(dx * dx + dy * dy);
}
export function easeOutQuad(t: number) {
  'worklet';
  const u = 1 - clamp(t, 0, 1);
  return 1 - u * u;
}
// Radius of the reveal front. At progress 1 the whole ring (2.5 widths) has left the box.
export function frontRadius(progress: number, maxRadius: number, ringWidth: number) {
  'worklet';
  return easeOutQuad(progress) * (maxRadius + ringWidth * 2.5);
}
// The wave fades out as the front travels, so the settled state is flat and exact.
export function waveAmplitude(progress: number, amplitude: number) {
  'worklet';
  const left = 1 - clamp(progress, 0, 1);
  return amplitude * left * left;
}
// Signed offset applied along the radial direction. `edge` is distance - frontRadius.
export function waveOffset(edge: number, ringWidth: number, wavelength: number, amp: number) {
  'worklet';
  const envelope = Math.exp(-Math.abs(edge) / Math.max(1, ringWidth));
  return Math.sin((edge / Math.max(1, wavelength)) * Math.PI * 2) * envelope * amp;
}
// 0 well inside the revealed area, 1 outside, with a short soft edge so it never aliases.
export function coverage(edge: number, soft: number) {
  'worklet';
  const t = clamp((edge + soft) / (2 * soft), 0, 1);
  return t * t * (3 - 2 * t);
}
// Everything the shader needs, in the order the SkSL declares it.
export function rippleUniforms(progress: number, origin: RipplePoint, oldIsB: boolean, reduce: boolean, cfg: RippleConfig) {
  'worklet';
  const max = farthestCorner(origin.x, origin.y, cfg.width, cfg.height);
  return {
    size: [cfg.width, cfg.height],
    origin: [origin.x, origin.y],
    radius: frontRadius(progress, max, cfg.ringWidth),
    ring: cfg.ringWidth,
    wavelength: cfg.wavelength,
    amp: reduce ? 0 : waveAmplitude(progress, cfg.amplitude),
    oldIsB: oldIsB ? 1 : 0,
    fade: reduce ? clamp(progress, 0, 1) : -1,
  };
}
// One pixel of the reveal, in plain JS. The web preview runs this; the SkSL mirrors it.
export function samplePoint(px: number, py: number, u: ReturnType<typeof rippleUniforms>) {
  'worklet';
  const dx = px - u.origin[0], dy = py - u.origin[1];
  const d = Math.sqrt(dx * dx + dy * dy);
  const edge = d - u.radius;
  const off = waveOffset(edge, u.ring, u.wavelength, u.amp);
  const k = d > 0.0001 ? off / d : 0;
  const mix = u.fade >= 0 ? 1 - u.fade : coverage(edge, 1.5);
  return { x: px + dx * k, y: py + dy * k, over: 1 - mix, crest: Math.abs(off) / Math.max(1e-6, u.amp || 1e-6) };
}

import React, { useMemo, useState } from 'react';
import { Pressable, Text, View } from 'react-native';
import { Shader, Skia } from '@shopify/react-native-skia';
import { RippleReveal, type RippleFeedback, type RippleSize } from './RippleReveal';

// Two original "artworks", each a small SkSL shader: soft colour blobs on a gradient.
const ART = `
uniform float2 size;
uniform float3 top;
uniform float3 bottom;
uniform float3 blobA;
uniform float3 blobB;
half4 main(float2 p) {
  float2 uv = p / size;
  float3 c = mix(top, bottom, uv.y);
  float a = smoothstep(0.55, 0.0, distance(uv, float2(0.22, 0.28)));
  float b = smoothstep(0.62, 0.0, distance(uv, float2(0.82, 0.78)));
  c = mix(c, blobA, a * 0.85);
  c = mix(c, blobB, b * 0.8);
  return half4(half3(c), 1.0);
}`;
const art = Skia.RuntimeEffect.Make(ART);
const dusk = { top: [0.07, 0.09, 0.2], bottom: [0.16, 0.1, 0.3], blobA: [0.35, 0.3, 0.85], blobB: [0.9, 0.4, 0.55] };
const dawn = { top: [1.0, 0.93, 0.8], bottom: [0.99, 0.8, 0.62], blobA: [1.0, 0.65, 0.35], blobB: [0.55, 0.78, 0.7] };
const make = (colors: typeof dusk) => ({ width, height }: RippleSize) => art ? <Shader source={art} uniforms={{ size: [width, height], ...colors }} /> : null;

export default function Example({ onFeedback }: { onFeedback?: (event: RippleFeedback) => void }) {
  const [showing, setShowing] = useState<'a' | 'b'>('a');
  const [reduce, setReduce] = useState<boolean | undefined>();
  const themeA = useMemo(() => make(dusk), []);
  const themeB = useMemo(() => make(dawn), []);
  return (
    <View style={{ paddingVertical: 24, width: '100%', alignItems: 'center' }}>
      <Text accessibilityLiveRegion="polite" style={{ color: '#31513b', fontSize: 13, marginBottom: 12 }}>Theme: {showing === 'a' ? 'Dusk' : 'Dawn'}</Text>
      <RippleReveal
        reducedMotion={reduce}
        width={300}
        height={200}
        themeA={themeA}
        themeB={themeB}
        label="Switch between Dusk and Dawn"
        onChange={setShowing}
        onFeedback={onFeedback}
        overlay={current => <View style={{ flex: 1, padding: 20, justifyContent: 'flex-end' }}><Text style={{ color: current === 'a' ? '#f1eefc' : '#3d2a14', fontSize: 22, fontWeight: '700' }}>{current === 'a' ? 'Dusk' : 'Dawn'}</Text><Text style={{ color: current === 'a' ? '#c9c2ee' : '#7a5a35', fontSize: 13 }}>Tap anywhere to switch</Text></View>}
      />
      <Text style={{ color: '#4b6053', fontSize: 12, marginTop: 12 }}>Tap anywhere on the card.</Text>
      <Pressable accessibilityRole="switch" accessibilityState={{ checked: reduce === true }} accessibilityLabel="Reduced motion" onPress={() => setReduce(reduce === true ? undefined : true)} style={{ marginTop: 8, minHeight: 44, paddingHorizontal: 16, borderRadius: 14, backgroundColor: '#e6edde', justifyContent: 'center' }}><Text style={{ color: '#31513b', fontSize: 13 }}>Motion: {reduce === true ? 'reduced' : 'system'}</Text></Pressable>
    </View>
  );
}

# Theme Reveal

A theme-switch transition, like a dark and light mode change that spreads out from the tap. The component is exported as `RippleReveal` and lives in `ripple-reveal/`; only its display name is Theme Reveal. Original tap-to-reveal transition. Touch a themed surface and a second theme spreads out from your finger, with a wave that rides the front of the reveal and fades as it travels. The effect is a Skia runtime shader (SkSL) driven by one Reanimated value. No copied demo code or assets.

Copy `RippleReveal.tsx` and `rippleMath.ts` together and keep LICENSE.

```tsx
<RippleReveal
  width={300}
  height={200}
  themeA={({ width, height }) => <LinearGradient start={vec(0, 0)} end={vec(0, height)} colors={['#14173a', '#2a1a4d']} />}
  themeB={({ width, height }) => <LinearGradient start={vec(0, 0)} end={vec(0, height)} colors={['#fff0cc', '#fdcc9e']} />}
  overlay={showing => <MyTitle theme={showing} />}
  onChange={showing => console.log(showing)}
/>
```

Dependencies: `@shopify/react-native-skia`, `react-native-reanimated` and `react-native-worklets` (Reanimated 4). In an Expo app run `npx expo install @shopify/react-native-skia react-native-reanimated react-native-worklets`. Skia runs on iOS, Android and web; on web it needs CanvasKit, see the Skia docs. Optional: `expo-haptics`, used only by the demo adapter.

How it works: the two themes are child shaders of one runtime shader. For each pixel the shader measures the distance `d` from the tap and compares it with the front radius. Pixels behind the front show the new theme, pixels ahead show the old one, with a 3px soft edge. Around the front it samples both themes at a point pushed along the radius by `sin(edge / wavelength) * exp(-|edge| / ring) * amplitude`, which makes the ripple, and adds a faint highlight on the crest. One timed `progress` value moves the front out past the farthest corner and shrinks the amplitude to zero, so the settled state is flat and exact. The geometry lives in `rippleMath.ts` as plain worklets, so it is unit tested without a device.

Props: `width`, `height`, `themeA`, `themeB` (functions returning a Skia shader node, for example `LinearGradient`, `ImageShader` or your own `Shader`), `overlay` (RN content above the canvas, given the visible theme), `initial` (`a` or `b`), `label`, `durationMs`, `amplitude`, `wavelength`, `ringWidth`, `onChange`, `onFeedback` (`start`, `settle`), `reducedMotion`. A tap while a reveal is running is ignored. Themes are sampled by position, so they should fill the box.

Accessibility: the surface is one button with a label and hint, and it announces the theme it switched to. Keyboard Enter and Space on web start the reveal from the centre. System Reduce Motion or `reducedMotion` replaces the wave with a short cross-fade.

Verified: helper tests, TypeScript, Expo dependency check and web export, and the real source rendered with Skia CanvasKit on React Native Web. The shader runs per pixel on the GPU, but it has not been profiled on low-end hardware. The site preview is a separate canvas adapter that runs the same math in JavaScript, not Skia.

API docs checked: https://shopify.github.io/react-native-skia/docs/shaders/overview/, https://shopify.github.io/react-native-skia/docs/shaders/runtime-shader/, https://shopify.github.io/react-native-skia/docs/animations/reanimated/
